 public async Task<XayDungVanBanThamDinhDto> CreateAsync(TaoHoSoThamDinhRequest r,CancellationToken ct=default){var a=Actor(); var source=await db.BoHoSoNghiepVus.OrderByDescending(x=>x.CreatedAt).FirstOrDefaultAsync(x=>x.HoSoXayDungVanBanId==r.HoSoId&&x.LoaiBoHoSo==LoaiBoHoSo.TrinhThamDinh&&x.TrangThai==TrangThaiBoHoSo.DaGui&&!x.IsDeleted,ct)??throw new InvalidOperationException("Chưa có hồ sơ trình thẩm định đã gửi."); if(await Data(r.HoSoId,true,ct)!=null)throw new InvalidOperationException("Đã có hồ sơ thẩm định."); await using var tx=await db.Database.BeginTransactionAsync(ct); var b=new BoHoSoNghiepVu{HoSoXayDungVanBanId=r.HoSoId,BuocQuyTrinhId=source.BuocQuyTrinhId,LoaiBoHoSo=LoaiBoHoSo.ThamDinh,TrangThai=TrangThaiBoHoSo.Nhap,LanXuLy=await Next(r.HoSoId,source.BuocQuyTrinhId,ct),BoHoSoNguonId=source.Id,NguoiLapId=a.U,DonViLapId=a.D,CreatedBy=a.U.ToString()}; db.BoHoSoNghiepVus.Add(b); var d=new HoSoXayDungVanBanThamDinh{BoHoSoNghiepVuId=b.Id};db.HoSoXayDungVanBanThamDinhs.Add(d);var links=await db.BoHoSoNghiepVuTaiLieus.Where(x=>x.BoHoSoNghiepVuId==source.Id&&!x.IsDeleted).ToListAsync(ct);foreach(var x in links)db.BoHoSoNghiepVuTaiLieus.Add(new(){BoHoSoNghiepVuId=b.Id,HoSoXayDungVanBanFileId=x.HoSoXayDungVanBanFileId,LoaiTaiLieuId=x.LoaiTaiLieuId,HinhThucThem="KeThua",BoHoSoTaiLieuNguonId=x.Id,ThuTu=x.ThuTu,CreatedBy=a.U.ToString()});Log(r.HoSoId,b.Id,"TAO_HO_SO_THAM_DINH","Tạo hồ sơ thẩm định",a);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Dto(r.HoSoId,b,d);}
