 public async Task<IReadOnlyList<XayDungVanBanTaiLieuDto>?> GetTaiLieuAsync(Guid id,CancellationToken ct=default){var x=await Data(id,false,ct);if(x==null)return null;return await(from l in db.BoHoSoNghiepVuTaiLieus join f in db.HoSoXayDungVanBanFiles on l.HoSoXayDungVanBanFileId equals f.Id where l.BoHoSoNghiepVuId==x.B.Id&&!l.IsDeleted&&!f.IsDeleted select FD(f)).ToListAsync(ct);}
 public async Task<XayDungVanBanTaiLieuDto?> UploadTaiLieuAsync(Guid id,TaiTaiLieuThamDinhRequest r,CancellationToken ct=default){var a=Actor();var x=await Data(id,true,ct);if(x==null)return null;TiepNhan(x.B);if(r.LoaiTaiLieuId==Guid.Empty||r.NoiDung.Length==0)throw new InvalidOperationException("Thiếu tài liệu.");var name=Path.GetFileName(r.TenFile);var dir=Path.Combine(env.ContentRootPath,"uploads","xay-dung-van-ban",id.ToString("N"));Directory.CreateDirectory(dir);var store=$"{Guid.NewGuid():N}_{name}";var path=Path.Combine(dir,store);await using(var o=File.Create(path))await r.NoiDung.CopyToAsync(o,ct);try{var old=await db.HoSoXayDungVanBanFiles.Where(item=>item.HoSoXayDungVanBanId==id&&item.LoaiTaiLieuId==r.LoaiTaiLieuId&&!item.IsDeleted).ToListAsync(ct);foreach(var previous in old.Where(item=>item.IsCurrent))previous.IsCurrent=false;var uploadedFile=new HoSoXayDungVanBanFile{HoSoXayDungVanBanId=id,LoaiTaiLieuId=r.LoaiTaiLieuId,TenTaiLieu=r.TenTaiLieu,TenFile=name,DuongDanFile=Path.Combine("uploads","xay-dung-van-ban",id.ToString("N"),store).Replace('\\','/'),MimeType=r.MimeType,DungLuong=r.NoiDung.Length,PhienBan=old.Count==0?1:old.Max(z=>z.PhienBan)+1,NguoiTaiLenId=a.U,CreatedBy=a.U.ToString()};db.HoSoXayDungVanBanFiles.Add(uploadedFile);db.BoHoSoNghiepVuTaiLieus.Add(new(){BoHoSoNghiepVuId=x.B.Id,HoSoXayDungVanBanFileId=uploadedFile.Id,LoaiTaiLieuId=uploadedFile.LoaiTaiLieuId,HinhThucThem="TaoMoi",CreatedBy=a.U.ToString()});Log(id,x.B.Id,"TAI_TAI_LIEU_THAM_DINH",$"Tải tài liệu {r.TenTaiLieu}",a,uploadedFile.Id);await db.SaveChangesAsync(ct);return FD(uploadedFile);}catch{if(File.Exists(path))File.Delete(path);throw;}}
 public async Task<bool> DeleteTaiLieuAsync(Guid id,Guid lid,CancellationToken ct=default){var a=Actor();var x=await Data(id,true,ct);if(x==null)return false;TiepNhan(x.B);var l=await db.BoHoSoNghiepVuTaiLieus.FirstOrDefaultAsync(z=>z.Id==lid&&z.BoHoSoNghiepVuId==x.B.Id&&!z.IsDeleted,ct);if(l==null)return false;if(l.HinhThucThem=="KeThua")throw new InvalidOperationException("Không thể gỡ tài liệu kế thừa.");l.IsDeleted=true;Log(id,x.B.Id,"GO_TAI_LIEU_THAM_DINH","Gỡ tài liệu",a,l.HoSoXayDungVanBanFileId);await db.SaveChangesAsync(ct);return true;}
 public async Task<DieuKienGuiKetQuaThamDinhDto?> KiemTraAsync(Guid id,CancellationToken ct=default){var x=await Data(id,false,ct);if(x==null)return null;var c=await Conditions(x,ct);return new(c.Count==0,c);}
 public async Task<XayDungVanBanThamDinhDto?> YeuCauBoSungAsync(Guid id,YeuCauBoSungThamDinhRequest r,CancellationToken ct=default){var a=Actor();if(r.BuocQuyTrinhSoanThaoId==Guid.Empty||r.TrangThaiHoSoBoSungId==Guid.Empty||string.IsNullOrWhiteSpace(r.NoiDungYeuCauBoSung))throw new InvalidOperationException("Thiếu thông tin yêu cầu bổ sung.");var x=await Data(id,true,ct);if(x==null)return null;TiepNhan(x.B);x.D.NoiDungYeuCauBoSung=r.NoiDungYeuCauBoSung;x.D.HanBoSung=r.HanBoSung;await Move(id,x,a,r.BuocQuyTrinhSoanThaoId,r.TrangThaiHoSoBoSungId,"YEU_CAU_BO_SUNG",r.NoiDungYeuCauBoSung,ct);return Dto(id,x.B,x.D);}
 public async Task<XayDungVanBanThamDinhDto?> GuiKetQuaAsync(Guid id,GuiKetQuaThamDinhRequest r,CancellationToken ct=default){var a=Actor();var x=await Data(id,true,ct);if(x==null)return null;var c=await Conditions(x,ct);if(c.Count>0)throw new InvalidOperationException(string.Join(" ",c));x.D.NgayGuiKetQua=r.NgayGuiKetQua??DateTime.UtcNow;await Move(id,x,a,r.BuocQuyTrinhTiepTheoId,r.TrangThaiHoSoTiepTheoId,"GUI_KET_QUA_THAM_DINH","Gửi kết quả thẩm định",ct);return Dto(id,x.B,x.D);}
 public async Task<bool> HuyAsync(Guid id,CancellationToken ct=default){var a=Actor();var x=await Data(id,true,ct);if(x==null)return false;Nhap(x.B);x.B.IsDeleted=true;Log(id,x.B.Id,"HUY_THAM_DINH","Hủy hồ sơ thẩm định",a);await db.SaveChangesAsync(ct);return true;}
 public async Task<KetQuaSoSanhDuThaoDto?> SoSanhAsync(Guid id,SoSanhDuThaoRequest r,CancellationToken ct=default){var a=Actor();var fs=await db.HoSoXayDungVanBanFiles.Where(f=>f.HoSoXayDungVanBanId==id&&(f.Id==r.FileGocId||f.Id==r.FileSoSanhId)&&!f.IsDeleted).ToListAsync(ct);if(fs.Count!=2)throw new InvalidOperationException("Hai file phải thuộc cùng hồ sơ.");var p1=Path.Combine(env.ContentRootPath,fs.Single(f=>f.Id==r.FileGocId).DuongDanFile);var p2=Path.Combine(env.ContentRootPath,fs.Single(f=>f.Id==r.FileSoSanhId).DuongDanFile);var s1=ReadDocx(p1);var s2=ReadDocx(p2);var old=s1.Split('\n',StringSplitOptions.RemoveEmptyEntries);var now=s2.Split('\n',StringSplitOptions.RemoveEmptyEntries);var add=now.Count(z=>!old.Contains(z));var del=old.Count(z=>!now.Contains(z));var e=new HoSoXayDungVanBanSoSanhDuThao{HoSoXayDungVanBanId=id,FileGocId=r.FileGocId,FileSoSanhId=r.FileSoSanhId,SoNoiDungThem=add,SoNoiDungXoa=del,SoNoiDungSua=Math.Min(add,del),NoiDungSoSanhHtml=$"<pre class=\"removed\">{WebUtility.HtmlEncode(s1)}</pre><pre class=\"added\">{WebUtility.HtmlEncode(s2)}</pre>",CreatedBy=a.U.ToString()};db.HoSoXayDungVanBanSoSanhDuThaos.Add(e);await db.SaveChangesAsync(ct);return SD(e);}
