 private async Task Move(Guid id,ThamDinhData x,A a,Guid b,Guid s,string action,string msg,CancellationToken ct){if(b==Guid.Empty||s==Guid.Empty)throw new InvalidOperationException("Thiếu bước hoặc trạng thái.");await using var tx=await db.Database.BeginTransactionAsync(ct);x.B.TrangThai=TrangThaiBoHoSo.DaHoanThanh;x.B.NgayHoanThanh=DateTime.UtcNow;var h=await db.HoSoXayDungVanBans.FirstAsync(z=>z.Id==id,ct);var pb=h.BuocHienTaiId;var ps=h.TrangThaiHoSoId;h.BuocHienTaiId=b;h.TrangThaiHoSoId=s;Log(id,x.B.Id,action,msg,a,null,pb,b,ps,s);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);}
 private async Task<List<string>> Conditions(ThamDinhData x,CancellationToken ct){var c=new List<string>();if(string.IsNullOrWhiteSpace(x.D.KetQuaThamDinh))c.Add("Chưa có kết quả thẩm định.");if(string.IsNullOrWhiteSpace(x.D.NoiDungKetLuan))c.Add("Chưa có kết luận thẩm định.");if(!await db.BoHoSoNghiepVuTaiLieus.AnyAsync(z=>z.BoHoSoNghiepVuId==x.B.Id&&!z.IsDeleted,ct))c.Add("Chưa có tài liệu.");return c;}
 private async Task<ThamDinhData?> Data(Guid id,bool t,CancellationToken ct){var b=t?db.BoHoSoNghiepVus:db.BoHoSoNghiepVus.AsNoTracking();var d=t?db.HoSoXayDungVanBanThamDinhs:db.HoSoXayDungVanBanThamDinhs.AsNoTracking();return await(from x in b join y in d on x.Id equals y.BoHoSoNghiepVuId where x.HoSoXayDungVanBanId==id&&x.LoaiBoHoSo==LoaiBoHoSo.ThamDinh&&!x.IsDeleted orderby x.CreatedAt descending select new ThamDinhData(x,y)).FirstOrDefaultAsync(ct);}
 private async Task<int> Next(Guid h,Guid b,CancellationToken ct)=>(await db.BoHoSoNghiepVus.Where(x=>x.HoSoXayDungVanBanId==h&&x.BuocQuyTrinhId==b).Select(x=>(int?)x.LanXuLy).MaxAsync(ct)??0)+1; private static void Nhap(BoHoSoNghiepVu b){if(b.TrangThai!=TrangThaiBoHoSo.Nhap)throw new InvalidOperationException("Hồ sơ không ở trạng thái nhập.");} private static void TiepNhan(BoHoSoNghiepVu b){if(b.TrangThai!=TrangThaiBoHoSo.DaTiepNhan)throw new InvalidOperationException("Hồ sơ chưa được tiếp nhận.");}
 private A Actor(){if(!user.IsAuthenticated||user.UserId is not Guid u||user.DonViId is not Guid d)throw new UnauthorizedAccessException();return new(u,d);} private void Log(Guid h,Guid b,string ac,string n,A a,Guid? f=null,Guid? pb=null,Guid? nb=null,Guid? ps=null,Guid? ns=null)=>db.HoSoXayDungVanBanLichSuXuLys.Add(new(){HoSoXayDungVanBanId=h,BoHoSoNghiepVuId=b,HanhDong=ac,NoiDung=n,NguoiXuLyId=a.U,DonViXuLyId=a.D,HoSoXayDungVanBanFileId=f,BuocQuyTrinhTruocId=pb,BuocQuyTrinhSauId=nb,TrangThaiTruocId=ps,TrangThaiSauId=ns,CreatedBy=a.U.ToString()});
 private static string ReadDocx(string p){using var z=ZipFile.OpenRead(p);var e=z.GetEntry("word/document.xml")??throw new InvalidOperationException("File không phải DOCX hợp lệ.");using var s=e.Open();var x=XDocument.Load(s);return string.Join('\n',x.Descendants().Where(n=>n.Name.LocalName=="p").Select(n=>string.Concat(n.Descendants().Where(t=>t.Name.LocalName=="t").Select(t=>t.Value))));} private static XayDungVanBanThamDinhDto Dto(Guid h,BoHoSoNghiepVu b,HoSoXayDungVanBanThamDinh d)=>new(h,b.Id,b.TrangThai.ToString(),d.NgayTiepNhan,d.HinhThucThamDinh,d.NgayThamDinh,d.KetQuaThamDinh,d.NoiDungKetLuan,d.NoiDungYeuCauBoSung,d.HanBoSung,d.NguoiKetLuanId); private static XayDungVanBanTaiLieuDto FD(HoSoXayDungVanBanFile f)=>new(f.Id,f.LoaiTaiLieuId,f.TenTaiLieu,f.PhienBan,f.TenFile,f.DuongDanFile,f.MimeType,f.DungLuong,f.IsCurrent,f.NgayTaiLen);private static KetQuaSoSanhDuThaoDto SD(HoSoXayDungVanBanSoSanhDuThao e)=>new(e.Id,e.HoSoXayDungVanBanId,e.FileGocId,e.FileSoSanhId,e.SoNoiDungThem,e.SoNoiDungXoa,e.SoNoiDungSua,e.NoiDungSoSanhHtml,e.CreatedAt);private sealed record ThamDinhData(BoHoSoNghiepVu B,HoSoXayDungVanBanThamDinh D);private sealed record A(Guid U,Guid D);
